// GIVEN — do not change.
public class Order {
    private final String code;
    private final int quantity;
    private final long price;

    public Order(String code, int quantity, long price) {
        this.code = code;
        this.quantity = quantity;
        this.price = price;
    }

    public long value() {
        return quantity * price;
    }

    @Override
    public String toString() {
        return code + " x" + quantity + " @" + price;
    }
}

import java.util.Scanner;

// GIVEN — do not change.
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long total = 0;
        int lineNo = 0;
        while (sc.hasNextLine()) {
            String line = sc.nextLine();
            lineNo++;
            try {
                Order o = OrderParser.parse(line, lineNo);
                total += o.value();
                System.out.println("ok " + o);
            } catch (OrderFormatException e) {
                Throwable cause = e.getCause();
                System.out.println("skip " + e.getMessage() + " [line " + e.getLineNo() + ", cause: "
                        + (cause == null ? "none" : cause.getClass().getSimpleName()) + "]");
            }
        }
        System.out.println("total " + total);
    }
}

public class OrderFormatException extends Exception { // TODO: lineNo, message "line N: …", cause
    public OrderFormatException(int lineNo, String message, Throwable cause) {
    }

    public int getLineNo() {
        return 0;
    }
}

public class OrderParser {
    public static Order parse(String line, int lineNo) throws OrderFormatException {
        String[] p = line.split(";");
        return new Order(p[0].trim(), Integer.parseInt(p[1].trim()), Long.parseLong(p[2].trim())); // TODO: wrap the failures
    }
}

